/**
 * Test critical data isolation requirement between organizations for reports.
 *
 * This test validates that reports from one organization are NEVER visible
 * to users of another organization, ensuring strict data isolation.
 *
 * Test flow:
 * 1. Create admin in Organization A and generate reports
 * 2. Create admin in Organization B (separate organization context)
 * 3. Verify Organization A's reports are NOT accessible via Organization B's ID
 * 4. Validate that Organization B can only see its own reports
 */
export async function test_api_report_data_isolation_between_organizations(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create admin in Organization A
  const adminA: IErpHrmAdmin.IAuthorized = await authorize_admin_join(
    connection,
    {
      body: {
        email: typia.random<string & tags.Format<"email">>(),
        password: "TestPass123!",
        display_name: RandomGenerator.name(),
        href: typia.random<string & tags.Format<"uri">>(),
        referrer: typia.random<string & tags.Format<"uri">>(),
      },
    },
  );
  typia.assert(adminA);
  const orgAId: string & tags.Format<"uuid"> = adminA.id satisfies string &
    tags.Format<"uuid">;
  // Create connection with Organization A's authorization
  const orgAConnection: api.IConnection = { host: connection.host };
  orgAConnection.headers = {
    Authorization: `Bearer ${adminA.token.access}`,
  };
  // 2. Create multiple reports in Organization A
  const report1: IErpHrmReport =
    await generate_random_erp_hrm_admin_organizations_reports_create(
      orgAConnection,
      {
        params: { organizationId: orgAId },
      },
    );
  typia.assert(report1);
  const report2: IErpHrmReport =
    await generate_random_erp_hrm_admin_organizations_reports_create(
      orgAConnection,
      {
        params: { organizationId: orgAId },
      },
    );
  typia.assert(report2);
  // Verify Organization A's reports exist
  const orgAReports: IPageIErpHrmReport.ISummary =
    await api.functional.erpHrm.admin.organizations.reports.index(
      orgAConnection,
      {
        organizationId: orgAId,
        body: {} satisfies IErpHrmReport.IRequest,
      },
    );
  typia.assert(orgAReports);
  TestValidator.predicate(
    "Organization A has reports",
    orgAReports.data.length >= 2,
  );
  // 3. Create admin in Organization B (different organization)
  const adminB: IErpHrmAdmin.IAuthorized = await authorize_admin_join(
    connection,
    {
      body: {
        email: typia.random<string & tags.Format<"email">>(),
        password: "TestPass123!",
        display_name: RandomGenerator.name(),
        href: typia.random<string & tags.Format<"uri">>(),
        referrer: typia.random<string & tags.Format<"uri">>(),
      },
    },
  );
  typia.assert(adminB);
  const orgBId: string & tags.Format<"uuid"> = adminB.id satisfies string &
    tags.Format<"uuid">;
  // Create connection with Organization B's authorization
  const orgBConnection: api.IConnection = { host: connection.host };
  orgBConnection.headers = {
    Authorization: `Bearer ${adminB.token.access}`,
  };
  // 4. CRITICAL: Attempt to access Organization A's reports using Organization B's context
  // This should return EMPTY results - enforcing data isolation
  const crossOrgReports: IPageIErpHrmReport.ISummary =
    await api.functional.erpHrm.admin.organizations.reports.index(
      orgBConnection,
      {
        organizationId: orgBId,
        body: {} satisfies IErpHrmReport.IRequest,
      },
    );
  typia.assert(crossOrgReports);
  // Validate: Organization A's reports should NOT be visible in Organization B
  TestValidator.equals(
    "Organization B has no access to Organization A's reports",
    crossOrgReports.data.length,
    0,
  );
  // Verify Organization A's report IDs are NOT in Organization B's results
  const orgAReportIds = [report1.id, report2.id];
  for (const orgAReportId of orgAReportIds) {
    TestValidator.equals(
      `Report ${orgAReportId} from Org A is not in Org B's results`,
      crossOrgReports.data.some(
        (r: IErpHrmReport.ISummary) => r.id === orgAReportId,
      ),
      false,
    );
  }
  // 5. Create a report in Organization B and verify it's the only one visible
  const reportInOrgB: IErpHrmReport =
    await generate_random_erp_hrm_admin_organizations_reports_create(
      orgBConnection,
      {
        params: { organizationId: orgBId },
      },
    );
  typia.assert(reportInOrgB);
  // Verify Organization B now has exactly 1 report
  const orgBReports: IPageIErpHrmReport.ISummary =
    await api.functional.erpHrm.admin.organizations.reports.index(
      orgBConnection,
      {
        organizationId: orgBId,
        body: {} satisfies IErpHrmReport.IRequest,
      },
    );
  typia.assert(orgBReports);
  TestValidator.equals(
    "Organization B has exactly 1 report (its own)",
    orgBReports.data.length,
    1,
  );
  TestValidator.equals(
    "Organization B's report matches what was created",
    orgBReports.data[0]!.id,
    reportInOrgB.id,
  );
  // Final validation: Organization A's reports still not visible in Organization B
  const finalOrgBReports: IPageIErpHrmReport.ISummary =
    await api.functional.erpHrm.admin.organizations.reports.index(
      orgBConnection,
      {
        organizationId: orgBId,
        body: {} satisfies IErpHrmReport.IRequest,
      },
    );
  typia.assert(finalOrgBReports);
  for (const orgAReportId of orgAReportIds) {
    TestValidator.equals(
      `Report ${orgAReportId} from Org A still not visible in Org B`,
      finalOrgBReports.data.some(
        (r: IErpHrmReport.ISummary) => r.id === orgAReportId,
      ),
      false,
    );
  }
}

