export async function test_api_project_member_assignment_as_project_lead(
  connection: api.IConnection,
): Promise<void> {
  // 1. Authenticate as a member to establish organization context and obtain project:manage permission
  const memberConnection: api.IConnection = { host: connection.host };
  const memberAuth = await authorize_member_join(memberConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      displayName: RandomGenerator.name(),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    },
  });
  typia.assert(memberAuth);
  // 2. Create a project container for assigning the project lead
  const project = await generate_random_erp_hrm_member_projects_create(
    memberConnection,
    {
      body: {
        name: RandomGenerator.paragraph({ sentences: 2 }),
        color: "#3A7CA5" satisfies string & tags.Pattern<"^#[0-9A-Fa-f]{6}$">,
        status: "active",
      },
    },
  );
  typia.assert(project);
  // 3. Create employee record via invitation for assignment as project lead
  const employeeEmail = typia.random<string & tags.Format<"email">>();
  const invitation = await generate_random_erp_hrm_member_invitations_create(
    memberConnection,
    {
      body: {
        email: employeeEmail,
        position: "Project Lead" satisfies string & tags.MaxLength<100>,
      },
    },
  );
  typia.assert(invitation);
  // 4. Assign the employee to the project with project_lead role
  const projectMember =
    await api.functional.erpHrm.member.projects.members.create(
      memberConnection,
      {
        projectId: project.id,
        body: {
          name: project.name,
          color: project.color,
          status: "active",
        } satisfies IErpHrmProjectMember.ICreate,
      },
    );
  typia.assert(projectMember);
  // 5. Validate the response contains the project membership with project_lead role
  TestValidator.equals("project ID matches", projectMember.id, project.id);
  TestValidator.equals(
    "project name matches",
    projectMember.name,
    project.name,
  );
  TestValidator.equals(
    "project status is active",
    projectMember.status,
    "active",
  );
  TestValidator.predicate(
    "project has members",
    projectMember.project_members_count >= 0,
  );
  TestValidator.predicate(
    "project has tasks count",
    projectMember.tasks_count >= 0,
  );
}

