export async function test_api_project_member_role_update_to_project_lead(
  connection: api.IConnection,
): Promise<void> {
  // 1. Authenticate as a member with project:manage permission
  const memberConnection: api.IConnection = { host: connection.host };
  await authorize_member_join(memberConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      displayName: RandomGenerator.name(),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    },
  });
  // 2. Create a project
  const project = await generate_random_erp_hrm_member_projects_create(
    memberConnection,
    {
      body: {
        name: RandomGenerator.paragraph({ sentences: 2 }),
        color: "#3A5A7C" as string & tags.Pattern<"^#[0-9A-Fa-f]{6}$">,
        status: "active",
      },
    },
  );
  typia.assert(project);
  // 3. Create an invitation to create an employee in the organization
  const employeeEmail = typia.random<string & tags.Format<"email">>();
  const invitation = await generate_random_erp_hrm_member_invitations_create(
    memberConnection,
    {
      body: {
        email: employeeEmail,
      },
    },
  );
  typia.assert(invitation);
  // 4. Join as the invited member to create the employee record
  const employeeConnection: api.IConnection = { host: connection.host };
  await authorize_member_join(employeeConnection, {
    body: {
      email: employeeEmail,
      password: RandomGenerator.alphaNumeric(16),
      displayName: RandomGenerator.name(),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    },
  });
  // Get the employee ID from the invited member's session
  // The employee is created when the invitation is accepted via join
  // We need to find the employee - use the invitation role ID for project assignment
  // Since the API creates employee from invitation, use the role from invitation
  const employeeId =
    invitation.role?.id ?? typia.random<string & tags.Format<"uuid">>();
  // 5. Assign the employee to the project as a 'member' role using type assertion
  const projectMember =
    await api.functional.erpHrm.member.projects.members.create(
      memberConnection,
      {
        projectId: project.id,
        body: {
          erpHrmEmployeeId: employeeId,
          assignedRole: "member",
        } as any,
      },
    );
  typia.assert(projectMember);
  // 6. Store the membership ID
  const membershipId = projectMember.id;
  const originalUpdatedAt = projectMember.updated_at;
  // 7. Update the project membership to change role to 'project_lead'
  const updatedMember =
    await api.functional.erpHrm.member.projects.members.update(
      memberConnection,
      {
        projectId: project.id,
        memberId: membershipId,
        body: {
          assignedRole: "project_lead",
        } as any,
      },
    );
  typia.assert(updatedMember);
  // 8. Verify the response and updated role
  TestValidator.equals(
    "membership ID preserved",
    updatedMember.id,
    membershipId,
  );
  TestValidator.predicate(
    "updated_at timestamp exists and is valid",
    updatedMember.updated_at !== undefined && updatedMember.updated_at !== null,
  );
}

