export async function test_api_timesheet_timelog_addition_to_draft(
  connection: api.IConnection,
): Promise<void> {
  // 1. Admin authenticates via POST /erpHrm/auth/admin/join
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_admin_join(adminConnection, {});
  // 2. Member authenticates (join) - member actor needed for creating timesheet
  const memberConnection: api.IConnection = { host: connection.host };
  await authorize_member_join(memberConnection, {});
  // 3. Create project via POST /erpHrm/member/projects with color=#FF5733, status=active
  const project = await generate_random_erp_hrm_member_projects_create(
    memberConnection,
    {
      body: {
        name: RandomGenerator.paragraph({ sentences: 2 }),
        color: "#FF5733" satisfies string &
          typia.tags.Pattern<"^#[0-9A-Fa-f]{6}$">,
        status: "active",
      },
    },
  );
  typia.assert(project);
  // 4. Create task via POST /erpHrm/member/projects/{projectId}/tasks
  const task = await generate_random_erp_hrm_member_projects_tasks_create(
    memberConnection,
    {
      params: { projectId: project.id },
      body: {
        title: "Design Module",
        priority: "medium",
      },
    },
  );
  typia.assert(task);
  // 5. Create timelog via POST /erpHrm/member/timelogs with date within current week
  // Get current week's Monday and Sunday
  const now = new Date();
  const dayOfWeek = now.getDay();
  const mondayOffset = dayOfWeek === 0 ? -6 : 1 - dayOfWeek;
  const monday = new Date(now);
  monday.setDate(now.getDate() + mondayOffset);
  monday.setHours(0, 0, 0, 0);
  const timelogDateISO = monday.toISOString();
  const timelog = await generate_random_erp_hrm_member_timelogs_create(
    memberConnection,
    {
      body: {
        projectId: project.id,
        taskId: task.id,
        date: timelogDateISO,
        durationMinutes: 120,
      },
    },
  );
  typia.assert(timelog);
  // 6. Create draft timesheet via POST /erpHrm/member/timesheets with week dates
  const sunday = new Date(monday);
  sunday.setDate(monday.getDate() + 6);
  const timesheet = await generate_random_erp_hrm_member_timesheets_create(
    memberConnection,
    {
      body: {
        week_start_date: monday.toISOString(),
        week_end_date: sunday.toISOString(),
      },
    },
  );
  typia.assert(timesheet);
  // 7. Verify timesheet was created with draft status
  TestValidator.equals("timesheet status is draft", timesheet.status, "draft");
  // 8. Call PATCH /erpHrm/admin/timesheets/{timesheetId}/timelogs to add timelog
  const updatedTimesheet =
    await api.functional.erpHrm.admin.timesheets.timelogs.update(
      adminConnection,
      {
        timesheetId: timesheet.id,
        body: {
          addTimelogIds: [timelog.id],
        } satisfies IErpHrmTimesheetTimelog.IUpdate,
      },
    );
  typia.assert(updatedTimesheet);
  // 9. Verify response returns timesheet with updated total_hours matching timelog duration (2.0 hours)
  TestValidator.equals(
    "total_hours is 2.0 (120 minutes = 2 hours)",
    updatedTimesheet.total_hours,
    2.0,
  );
  // 10. Verify timesheetTimelogs array now contains the timelog
  TestValidator.predicate(
    "timesheetTimelogs contains the added timelog",
    updatedTimesheet.timesheetTimelogs.some(
      (t) => t.erpHrmTimelog.id === timelog.id,
    ),
  );
  // 11. Verify status remains 'draft'
  TestValidator.equals(
    "status remains draft",
    updatedTimesheet.status,
    "draft",
  );
}

