export async function test_api_timesheet_timelog_removal_from_draft(
  connection: api.IConnection,
): Promise<void> {
  // 1. Admin authenticates
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_admin_join(adminConnection, {});
  // 2. Member joins and authenticates
  const memberConnection: api.IConnection = { host: connection.host };
  await authorize_member_join(memberConnection, {});
  // 3. Create project with color=#00FF00 and status=active
  const project = await generate_random_erp_hrm_member_projects_create(
    memberConnection,
    {
      body: {
        name: RandomGenerator.paragraph({ sentences: 1 }),
        color: "#00FF00" as "#00FF00",
        status: "active",
      } satisfies IErpHrmProjectMember.ICreate,
    },
  );
  typia.assert(project);
  // 4. Create timelog with date within current week and durationMinutes=180
  const now = new Date();
  const dayOfWeek = now.getDay();
  const daysToMonday = dayOfWeek === 0 ? 6 : dayOfWeek - 1;
  const weekStart = new Date(now);
  weekStart.setDate(now.getDate() - daysToMonday);
  weekStart.setHours(0, 0, 0, 0);
  const timelog = await generate_random_erp_hrm_member_timelogs_create(
    memberConnection,
    {
      body: {
        projectId: project.id,
        date: weekStart.toISOString(),
        durationMinutes: 180,
      },
    },
  );
  typia.assert(timelog);
  // 5. Create draft timesheet covering the current week (Monday to Sunday)
  const weekEnd = new Date(weekStart);
  weekEnd.setDate(weekStart.getDate() + 6);
  weekEnd.setHours(23, 59, 59, 999);
  const timesheet = await generate_random_erp_hrm_member_timesheets_create(
    memberConnection,
    {
      body: {
        week_start_date: weekStart.toISOString(),
        week_end_date: weekEnd.toISOString(),
      } satisfies IErpHrmTimesheet.ICreate,
    },
  );
  typia.assert(timesheet);
  // 6. Verify timesheet was created with timelog included (total_hours = 3.0)
  TestValidator.equals(
    "timesheet has one timelog",
    timesheet.timesheetTimelogs.length,
    1,
  );
  TestValidator.equals("total_hours equals 3.0", timesheet.total_hours, 3.0);
  TestValidator.equals("timesheet status is draft", timesheet.status, "draft");
  // 7. Call PATCH /erpHrm/admin/timesheets/{timesheetId}/timelogs to remove the timelog
  const updatedTimesheet =
    await api.functional.erpHrm.admin.timesheets.timelogs.update(
      adminConnection,
      {
        timesheetId: timesheet.id,
        body: {
          removeTimelogIds: [timelog.id],
        } satisfies IErpHrmTimesheetTimelog.IUpdate,
      },
    );
  typia.assert(updatedTimesheet);
  // 8. Verify response returns timesheet with updated total_hours = 0
  TestValidator.equals(
    "total_hours is 0 after removal",
    updatedTimesheet.total_hours,
    0,
  );
  // 9. Verify timesheetTimelogs array is now empty
  TestValidator.equals(
    "timesheetTimelogs is empty",
    updatedTimesheet.timesheetTimelogs.length,
    0,
  );
  // 10. Verify status remains 'draft'
  TestValidator.equals(
    "status remains draft",
    updatedTimesheet.status,
    "draft",
  );
}

