      id: true,
      name: true,
      color: true,
      status: true,
      budget_hours: true,
      start_date: true,
      end_date: true,
      created_at: true,
      organization: {
        select: {
          id: true,
          name: true,
          description: true,
          logo_uri: true,
          currency: true,
          timezone: true,
          fiscal_start_month: true,
          created_at: true,
          owner: {
            select: {
              id: true,
              display_name: true,
              email: true,
              avatar_uri: true,
              phone: true,
              created_at: true,
