import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";

import { MyGlobal } from "../MyGlobal";
import { ErpHrmInvitationCollector } from "../collectors/ErpHrmInvitationCollector";
import { MemberPayload } from "../decorators/payload/MemberPayload";
import { ErpHrmInvitationTransformer } from "../transformers/ErpHrmInvitationTransformer";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function postErpHrmMemberInvitations(props: {
  member: MemberPayload;
  body: IErpHrmInvitation.ICreate;
}): Promise<IErpHrmInvitation> {
  // Get member's employee record to determine organization and permissions
  const employee = await MyGlobal.prisma.erp_hrm_employees.findFirst({
    where: {
      erp_hrm_member_id: props.member.id,
      deleted_at: null,
    },
    select: {
      id: true,
      erp_hrm_organization_id: true,
      erp_hrm_role_id: true,
    },
  });
  if (!employee) {
    throw new HttpException("Forbidden", 403);
  }
  // Verify employee:manage permission by checking role_permissions table directly
  const rolePermissions =
    await MyGlobal.prisma.erp_hrm_role_permissions.findMany({
      where: {
        erp_hrm_role_id: employee.erp_hrm_role_id,
      },
      select: {
        permission: true,
      },
    });
  const hasEmployeeManagePermission = rolePermissions.some(
    (p) => p.permission === "employee:manage",
  );
  if (!hasEmployeeManagePermission) {
    throw new HttpException("Forbidden", 403);
  }
  // Get organization details
  const organization =
    await MyGlobal.prisma.erp_hrm_organizations.findUniqueOrThrow({
      where: { id: employee.erp_hrm_organization_id },
      select: { id: true },
    });
  // Validate role if provided
  if (props.body.erpHrmRoleId) {
    const role = await MyGlobal.prisma.erp_hrm_roles.findFirst({
      where: {
        id: props.body.erpHrmRoleId,
        erp_hrm_organization_id: employee.erp_hrm_organization_id,
        deleted_at: null,
      },
    });
    if (!role) {
      throw new HttpException("Invalid role for this organization", 400);
    }
  }
  // Validate department if provided
  if (props.body.erpHrmDepartmentId) {
    const department = await MyGlobal.prisma.erp_hrm_departments.findFirst({
      where: {
        id: props.body.erpHrmDepartmentId,
        erp_hrm_organization_id: employee.erp_hrm_organization_id,
        deleted_at: null,
      },
    });
    if (!department) {
      throw new HttpException("Invalid department for this organization", 400);
    }
  }
  // Check for duplicate invitation (pending or accepted)
  const existingInvitation =
    await MyGlobal.prisma.erp_hrm_invitations.findFirst({
      where: {
        erp_hrm_organization_id: employee.erp_hrm_organization_id,
        email: props.body.email,
        status: { in: ["pending", "accepted"] },
        deleted_at: null,
      },
    });
  if (existingInvitation) {
    throw new HttpException("Invitation already exists for this email", 409);
  }
  // Check if existing user with this email
  const existingMember = await MyGlobal.prisma.erp_hrm_members.findFirst({
    where: {
      email: props.body.email,
      deleted_at: null,
    },
  });
  // Create invitation using transaction
  const result = await MyGlobal.prisma.$transaction(async (tx) => {
    // Create invitation
    const invitation = await tx.erp_hrm_invitations.create({
      data: await ErpHrmInvitationCollector.collect({
        body: props.body,
        erpHrmOrganizations: organization,
      }),
      ...ErpHrmInvitationTransformer.select(),
    });
    let employeeCreated = false;
    // If existing user found, create employee immediately
    if (existingMember) {
      // Check if employee already exists in this organization
      const existingEmployee = await tx.erp_hrm_employees.findFirst({
        where: {
          erp_hrm_member_id: existingMember.id,
          erp_hrm_organization_id: employee.erp_hrm_organization_id,
          deleted_at: null,
        },
      });
      if (!existingEmployee) {
        // Determine role_id - either from body, or lookup default Employee role
        let roleId: string;
        if (props.body.erpHrmRoleId) {
          roleId = props.body.erpHrmRoleId;
        } else {
          const defaultRole = await tx.erp_hrm_roles.findFirst({
            where: {
              erp_hrm_organization_id: employee.erp_hrm_organization_id,
              name: "Employee",
              is_builtin: true,
              deleted_at: null,
            },
          });
          if (!defaultRole) {
            throw new HttpException("Default Employee role not found", 500);
          }
          roleId = defaultRole.id;
        }
        // Create employee record
        await tx.erp_hrm_employees.create({
          data: {
            id: v4(),
            erp_hrm_member_id: existingMember.id,
            erp_hrm_organization_id: employee.erp_hrm_organization_id,
            erp_hrm_role_id: roleId,
            erp_hrm_department_id: props.body.erpHrmDepartmentId ?? null,
            position: props.body.position ?? null,
            employment_type: "full-time",
            status: "active",
            created_at: new Date(),
            updated_at: new Date(),
            deleted_at: null,
          },
        });
        employeeCreated = true;
      }
      // Update invitation to accepted status
      const updatedInvitation = await tx.erp_hrm_invitations.update({
        where: { id: invitation.id },
        data: {
          status: "accepted",
          accepted_at: new Date(),
          updated_at: new Date(),
        },
        ...ErpHrmInvitationTransformer.select(),
      });
      // Log activity
      await tx.erp_hrm_activity_logs.create({
        data: {
          id: v4(),
          erp_hrm_organization_id: employee.erp_hrm_organization_id,
          erp_hrm_member_id: props.member.id,
          action_type: "invitation.accepted",
          target_entity_type: "invitation",
          target_entity_id: invitation.id,
          details: JSON.stringify({
            invitation_id: invitation.id,
            employee_created: employeeCreated,
          }),
          created_at: new Date(),
        },
      });
      return { invitation: updatedInvitation, employeeCreated };
    }
    // For new user, log pending invitation creation
    await tx.erp_hrm_activity_logs.create({
      data: {
        id: v4(),
        erp_hrm_organization_id: employee.erp_hrm_organization_id,
        erp_hrm_member_id: props.member.id,
        action_type: "invitation.create",
        target_entity_type: "invitation",
        target_entity_id: invitation.id,
        details: JSON.stringify({
          invitation_id: invitation.id,
        }),
        created_at: new Date(),
      },
    });
    return { invitation, employeeCreated: false };
  });
  return await ErpHrmInvitationTransformer.transform(result.invitation);
}

import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { ArrayUtil } from "@nestia/e2e";
import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";

import { MyGlobal } from "../MyGlobal";
import { MemberPayload } from "../decorators/payload/MemberPayload";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function deleteErpHrmMemberProjectsProjectIdMembersMemberId(props: {
  member: MemberPayload;
  projectId: string & tags.Format<"uuid">;
  memberId: string & tags.Format<"uuid">;
}): Promise<void> {
  // Find the project to verify it exists and get organization context
  const project = await MyGlobal.prisma.erp_hrm_projects.findUniqueOrThrow({
    where: { id: props.projectId },
    select: { id: true, erp_hrm_organization_id: true },
  });
  // Find the requesting member's employee record in the same organization
  const requesterEmployee = await MyGlobal.prisma.erp_hrm_employees.findFirst({
    where: {
      erp_hrm_member_id: props.member.id,
      erp_hrm_organization_id: project.erp_hrm_organization_id,
      deleted_at: null,
    },
    select: {
      id: true,
      erp_hrm_role_id: true,
    },
  });
  if (!requesterEmployee) {
    throw new HttpException("Forbidden", 403);
  }
  // Check if the requester has project:manage permission via role_permissions table
  const rolePermission =
    await MyGlobal.prisma.erp_hrm_role_permissions.findFirst({
      where: {
        erp_hrm_role_id: requesterEmployee.erp_hrm_role_id,
        permission: "project:manage",
      },
      select: { id: true },
    });
  if (!rolePermission) {
    throw new HttpException("Forbidden", 403);
  }
  // Verify project membership exists and belongs to the specified project
  await MyGlobal.prisma.erp_hrm_project_members.findUniqueOrThrow({
    where: {
      id: props.memberId,
      erp_hrm_project_id: props.projectId,
    },
    select: { id: true },
  });
  // Delete the project membership (historical timelogs are preserved automatically)
  await MyGlobal.prisma.erp_hrm_project_members.delete({
    where: { id: props.memberId },
  });
}

import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { IErpHrmActivityLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IErpHrmActivityLog";
import { ArrayUtil } from "@nestia/e2e";
import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";

import { MyGlobal } from "../MyGlobal";
import { AdminPayload } from "../decorators/payload/AdminPayload";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function getErpHrmAdminOrganizationsOrganizationIdActivityLogsStatistics(props: {
  admin: AdminPayload;
  organizationId: string & tags.Format<"uuid">;
}): Promise<IErpHrmActivityLog[]> {
  // Validate organization exists
  await MyGlobal.prisma.erp_hrm_organizations.findUniqueOrThrow({
    where: { id: props.organizationId },
    select: { id: true },
  });
  // Query aggregated statistics grouped by action_type
  const statistics = await MyGlobal.prisma.erp_hrm_activity_logs.groupBy({
    by: ["action_type"],
    where: {
      erp_hrm_organization_id: props.organizationId,
    },
    _count: {
      action_type: true,
    },
  });
  // Transform aggregated results to response DTO format
  return statistics.map(
    (stat): IErpHrmActivityLog => ({
      action_type: stat.action_type,
      count: stat._count.action_type as number & tags.Type<"int32">,
    }),
  );
}

import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { IErpHrmActivityLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IErpHrmActivityLog";
import { IErpHrmMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IErpHrmMember";
import { IErpHrmOrganization } from "@ORGANIZATION/PROJECT-api/lib/structures/IErpHrmOrganization";
import { ArrayUtil } from "@nestia/e2e";
import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";

import { MyGlobal } from "../MyGlobal";
import { MemberPayload } from "../decorators/payload/MemberPayload";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function getErpHrmMemberOrganizationsOrganizationIdDashboard(props: {
  member: MemberPayload;
  organizationId: string & tags.Format<"uuid">;
}): Promise<IErpHrmOrganization> {
  // Step 1: Validate organization exists
  const organization =
    await MyGlobal.prisma.erp_hrm_organizations.findUniqueOrThrow({
      where: { id: props.organizationId },
      select: {
        id: true,
        name: true,
        currency: true,
        timezone: true,
      },
    });
  // Step 2: Verify member belongs to organization
  const employee = await MyGlobal.prisma.erp_hrm_employees.findFirst({
    where: {
      erp_hrm_member_id: props.member.id,
      erp_hrm_organization_id: props.organizationId,
      deleted_at: null,
    },
    select: {
      id: true,
      status: true,
    },
  });
  if (!employee) {
    throw new HttpException("Forbidden", 403);
  }
  // Step 3: Get organization timezone for date calculations
  const timezone = organization.timezone;
  // Helper to get start and end of current week/month in organization timezone
  const now = new Date();
  const orgNow = new Date(now.toLocaleString("en-US", { timeZone: timezone }));
  // Get start of current week (Sunday)
  const dayOfWeek = orgNow.getDay();
  const startOfWeek = new Date(orgNow);
  startOfWeek.setDate(orgNow.getDate() - dayOfWeek);
  startOfWeek.setHours(0, 0, 0, 0);
  // Get start of current month
  const startOfMonth = new Date(
    orgNow.getFullYear(),
    orgNow.getMonth(),
    1,
    0,
    0,
    0,
    0,
  );
  // Step 4: Query employee statistics
  const employeeStatsRaw = await MyGlobal.prisma.erp_hrm_employees.groupBy({
    by: ["status", "employment_type"],
    where: {
      erp_hrm_organization_id: props.organizationId,
      deleted_at: null,
    },
    _count: { id: true },
  });
  const employeeCount = await MyGlobal.prisma.erp_hrm_employees.count({
    where: {
      erp_hrm_organization_id: props.organizationId,
      deleted_at: null,
    },
  });
  const activeEmployees = employeeStatsRaw
    .filter((e) => e.status === "active")
    .reduce((sum, e) => sum + e._count.id, 0);
  const deactivatedEmployees = employeeStatsRaw
    .filter((e) => e.status === "deactivated")
    .reduce((sum, e) => sum + e._count.id, 0);
  const employeeStatistics = {
    total_count: employeeCount,
    by_status: {
      active: activeEmployees,
      deactivated: deactivatedEmployees,
    },
    by_employment_type: {
      full_time:
        employeeStatsRaw.find((e) => e.employment_type === "full-time")?._count
          .id ?? 0,
      part_time:
        employeeStatsRaw.find((e) => e.employment_type === "part-time")?._count
          .id ?? 0,
      contractor:
        employeeStatsRaw.find((e) => e.employment_type === "contractor")?._count
          .id ?? 0,
      intern:
        employeeStatsRaw.find((e) => e.employment_type === "intern")?._count
          .id ?? 0,
    },
  };
  // Step 5: Query project statistics
  const projectStatsRaw = await MyGlobal.prisma.erp_hrm_projects.groupBy({
    by: ["status"],
    where: {
      erp_hrm_organization_id: props.organizationId,
    },
    _count: { id: true },
    _sum: { budget_hours: true },
  });
  const totalProjects = projectStatsRaw.reduce(
    (sum, p) => sum + p._count.id,
    0,
  );
  const totalBudgetHours = projectStatsRaw.reduce(
    (sum, p) => sum + (p._sum.budget_hours ?? 0),
    0,
  );
  // Calculate utilized budget hours from timelogs
  const utilizedBudgetResult = await MyGlobal.prisma.erp_hrm_timelogs.aggregate(
    {
      where: {
        employee: {
          erp_hrm_organization_id: props.organizationId,
        },
      },
      _sum: { duration_minutes: true },
    },
  );
  const utilizedBudgetHours = utilizedBudgetResult._sum.duration_minutes
    ? utilizedBudgetResult._sum.duration_minutes / 60
    : null;
  const budgetUtilizationPercentage =
    totalBudgetHours && utilizedBudgetHours
      ? (utilizedBudgetHours / totalBudgetHours) * 100
      : null;
  const projectOverview = {
    total_count: totalProjects,
    by_status: {
      active:
        projectStatsRaw.find((p) => p.status === "active")?._count.id ?? 0,
      archived:
        projectStatsRaw.find((p) => p.status === "archived")?._count.id ?? 0,
      completed:
        projectStatsRaw.find((p) => p.status === "completed")?._count.id ?? 0,
    },
    total_budget_hours: totalBudgetHours > 0 ? totalBudgetHours : null,
    utilized_budget_hours: utilizedBudgetHours,
    budget_utilization_percentage: budgetUtilizationPercentage,
  };
  // Step 6: Query task metrics
  const projectIds = await MyGlobal.prisma.erp_hrm_projects.findMany({
    where: { erp_hrm_organization_id: props.organizationId },
    select: { id: true },
  });
  const projectIdList = projectIds.map((p) => p.id);
  const taskStatsRaw = await MyGlobal.prisma.erp_hrm_tasks.groupBy({
    by: ["status", "priority"],
    where: {
      erp_hrm_project_id: { in: projectIdList },
    },
    _count: { id: true },
  });
  const totalTasks = taskStatsRaw.reduce((sum, t) => sum + t._count.id, 0);
  const completedTasks = taskStatsRaw
    .filter((t) => t.status === "completed")
    .reduce((sum, t) => sum + t._count.id, 0);
  const completionRate =
    totalTasks > 0 ? (completedTasks / totalTasks) * 100 : 0;
  const taskMetrics = {
    total_count: totalTasks,
    by_status: {
      open: taskStatsRaw.find((t) => t.status === "open")?._count.id ?? 0,
      in_progress:
        taskStatsRaw.find((t) => t.status === "in-progress")?._count.id ?? 0,
      completed: completedTasks,
      closed: taskStatsRaw.find((t) => t.status === "closed")?._count.id ?? 0,
    },
    by_priority: {
      low: taskStatsRaw.find((t) => t.priority === "low")?._count.id ?? 0,
      medium: taskStatsRaw.find((t) => t.priority === "medium")?._count.id ?? 0,
      high: taskStatsRaw.find((t) => t.priority === "high")?._count.id ?? 0,
      urgent: taskStatsRaw.find((t) => t.priority === "urgent")?._count.id ?? 0,
    },
    completion_rate: completionRate,
  };
  // Step 7: Query time tracking aggregates (optimized: single query for monthly, filter in JS for weekly)
  const monthlyTimelogs = await MyGlobal.prisma.erp_hrm_timelogs.findMany({
    where: {
      employee: {
        erp_hrm_organization_id: props.organizationId,
      },
      date: { gte: startOfMonth },
    },
    select: {
      duration_minutes: true,
      billable: true,
      date: true,
    },
  });
  // Filter for weekly from monthly results
  const weeklyTimelogs = monthlyTimelogs.filter((t) => t.date >= startOfWeek);
  const hoursLoggedThisWeek =
    weeklyTimelogs.reduce((sum, t) => sum + t.duration_minutes, 0) / 60;
  const hoursLoggedThisMonth =
    monthlyTimelogs.reduce((sum, t) => sum + t.duration_minutes, 0) / 60;
  const billableHours =
    monthlyTimelogs
      .filter((t) => t.billable)
      .reduce((sum, t) => sum + t.duration_minutes, 0) / 60;
  const nonBillableHours =
    monthlyTimelogs
      .filter((t) => !t.billable)
      .reduce((sum, t) => sum + t.duration_minutes, 0) / 60;
  // Calculate days in current month
  const currentDay = orgNow.getDate();
  const averageDailyHours =
    currentDay > 0 ? hoursLoggedThisMonth / currentDay : 0;
  const timeTracking = {
    hours_logged_this_week: hoursLoggedThisWeek,
    hours_logged_this_month: hoursLoggedThisMonth,
    billable_hours: billableHours,
    non_billable_hours: nonBillableHours,
    average_daily_hours: averageDailyHours,
  };
  // Step 8: Query recent activity (last 10 entries)
  const recentActivityRaw =
    await MyGlobal.prisma.erp_hrm_activity_logs.findMany({
      where: {
        erp_hrm_organization_id: props.organizationId,
      },
      orderBy: { created_at: "desc" },
      take: 10,
      select: {
        id: true,
        action_type: true,
        target_entity_type: true,
        target_entity_id: true,
        member: {
          select: {
            id: true,
            email: true,
            display_name: true,
            avatar_uri: true,
            phone: true,
            created_at: true,
          },
        },
        created_at: true,
      },
    });
  const recentActivity: IErpHrmActivityLog.ISummary[] = recentActivityRaw.map(
    (log) => ({
      id: log.id as string & tags.Format<"uuid">,
      action_type: log.action_type,
      target_entity_type: log.target_entity_type,
      target_entity_id: log.target_entity_id as string & tags.Format<"uuid">,
      member: {
        id: log.member.id as string & tags.Format<"uuid">,
        email: log.member.email as string & tags.Format<"email">,
        displayName: log.member.display_name,
        avatarUri: log.member.avatar_uri,
        phone: log.member.phone,
        createdAt: toISOStringSafe(log.member.created_at),
      } satisfies IErpHrmMember.ISummary,
      created_at: toISOStringSafe(log.created_at),
    }),
  );
  // Step 9: Return comprehensive dashboard response
  return {
    organization: {
      id: organization.id as string & tags.Format<"uuid">,
      name: organization.name,
      employee_count: employeeCount,
      currency: organization.currency,
      timezone: organization.timezone,
    },
    employeeStatistics,
    projectOverview,
    taskMetrics,
    timeTracking,
    recentActivity,
  };
}

import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { IErpHrmAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IErpHrmAdmin";
import { IErpHrmGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/IErpHrmGuest";
import { IErpHrmMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IErpHrmMember";
import { IErpHrmMemberSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IErpHrmMemberSession";
import { ArrayUtil } from "@nestia/e2e";
import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
