          },
        },
        props.body.phone !== undefined && {
          phone: props.body.phone,
        },
      ] as (Prisma.erp_hrm_adminsWhereInput | false | null | undefined)[]
    ).filter(
      (item): item is Prisma.erp_hrm_adminsWhereInput =>
        item !== false && item !== null && item !== undefined,
