    admin: AdminPayload,
    @TypedParam("organizationId")
    organizationId: string & tags.Format<"uuid">,
    @TypedBody()
    body: IErpHrmReport.IRequest,
  ): Promise<IPageIErpHrmReport.ISummary> {
    try {
      return await patchErpHrmAdminOrganizationsOrganizationIdReports({
        admin,
        organizationId,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

