  public async erase(
    @AdminAuth()
    admin: AdminPayload,
    @TypedParam("departmentId")
    departmentId: string & tags.Format<"uuid">,
  ): Promise<void> {
    try {
      return await deleteErpHrmAdminDepartmentsDepartmentId({
        admin,
        departmentId,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }
}

