    body: IErpHrmContract.IRequest,
  ): Promise<IPageIErpHrmContract.ISummary> {
    try {
      return await patchErpHrmAdminEmployeesEmployeeIdContracts({
        admin,
        employeeId,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
